        {
          id: "web-languages",
          prompt: "Which languages are commonly used in web development?",
          choices: ["JavaScript", "TypeScript", "PHP", "COBOL"]
        }
      ];

      function ChoiceInput({ questionId, choice }) {
        const value = choice.toLowerCase().replace(/[^a-z0-9]+/g, "-");
        const inputId = `${questionId}-${value}`;

        return `
          <label class="choice" for="${inputId}">
            <input type="checkbox" id="${inputId}" name="${questionId}" value="${choice}">
