            <fieldset${describedBy}>
              <legend>${question.prompt}</legend>
              ${helpText}
              <div class="choices">
                ${choices}
              </div>
            </fieldset>
          </div>
        `;
      }

      function QuizApp({ questions }) {
        return questions.map((question) => QuestionField({ question })).join("");
      }

      document.getElementById("quiz-root").innerHTML = QuizApp({ questions: quizQuestions });
    </script>
