         const helpId = `${question.id}-help`;
         const describedBy = question.helpText ? ` aria-describedby="${helpId}"` : "";
         const helpText = question.helpText ? `<p class="help-text" id="${helpId}">${question.helpText}</p>` : "";
         const choices = question.choices
